const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const atlanta = ee.Geometry.Point([-84.3879, 33.7489]);
  const urbanArea = atlanta.buffer(30000); // 30 km buffer around Atlanta
  const scale = 1000; // Resolution for reduction in meters

  const july2013Start = '2013-07-01';
  const july2013End = '2013-07-31';
  const dec2013Start = '2013-12-01';
  const dec2013End = '2013-12-31';

  const bandName = 'avg_rad'; // Average Radiance for nighttime lights

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG');

  // Filter for July 2013
  const julyCollection = collection.filterDate(july2013Start, july2013End)
                                   .filterBounds(urbanArea);

  if (julyCollection.size().getInfo() === 0) {
    console.log("No VIIRS DNB data found for July 2013 in the specified area.");
    console.log("C1");
    return;
  }
  const julyImage = julyCollection.first();

  // Filter for December 2013
  const decCollection = collection.filterDate(dec2013Start, dec2013End)
                                  .filterBounds(urbanArea);

  if (decCollection.size().getInfo() === 0) {
    console.log("No VIIRS DNB data found for December 2013 in the specified area.");
    console.log("C1");
    return;
  }
  const decImage = decCollection.first();

  // 3. Processing - Calculate valid pixels and mean intensity
  // July 2013
  const julyStats = julyImage.select(bandName).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: urbanArea,
    scale: scale,
    maxPixels: 1e9
  });

  const julyMeanRad = julyStats.get(bandName).getInfo();
  const julyPixelCount = julyStats.get(bandName + '_count').getInfo();

  console.log(`July 2013 - Mean Radiance: ${julyMeanRad !== null ? julyMeanRad.toFixed(4) : 'N/A'}, Valid Pixels: ${julyPixelCount}`);

  if (julyPixelCount === 0 || julyMeanRad === null) {
    console.log("No valid pixels or failed calculation for July 2013 after processing.");
    console.log("C2");
    return;
  }

  // December 2013
  const decStats = decImage.select(bandName).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: urbanArea,
    scale: scale,
    maxPixels: 1e9
  });

  const decMeanRad = decStats.get(bandName).getInfo();
  const decPixelCount = decStats.get(bandName + '_count').getInfo();

  console.log(`Dec 2013 - Mean Radiance: ${decMeanRad !== null ? decMeanRad.toFixed(4) : 'N/A'}, Valid Pixels: ${decPixelCount}`);

  if (decPixelCount === 0 || decMeanRad === null) {
    console.log("No valid pixels or failed calculation for December 2013 after processing.");
    console.log("C2");
    return;
  }

  // 4. Calculation and Validation
  if (julyMeanRad === null || decMeanRad === null || isNaN(julyMeanRad) || isNaN(decMeanRad)) {
    console.log("Calculation resulted in None/NaN for mean radiance.");
    console.log("C3");
    return;
  }

  if (decMeanRad > julyMeanRad) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
